/// Target-declared exhaustive ownership partitions of the raw SVD singleton.
pub mod peripheral_ownership {

    /// Source-qualified MMIO views retained for bit-use coverage. No production transaction or read-safe snapshot exposes these tokens.
    pub struct UnexposedPeripherals {
        pub modem_ieee802154_observed: crate::ModemIeee802154Observed,
        pub modem_wifi_mac_observed: crate::ModemWifiMacObserved,
        pub modem_wifi_mac_power_observed: crate::ModemWifiMacPowerObserved,
    }

    /// IEEE 802.15.4 MAC and source-specific interrupt-route registers owned by the IEEE 802.15.4 hardware lifecycle.
    pub struct Ieee802154Peripherals {
        pub ieee802154_mac: crate::Ieee802154Mac,
        pub ieee802154_interrupt_route: crate::Ieee802154InterruptRoute,
    }

    /// Modem event-task matrix channels zero and one, programmed by the IEEE 802.15.4 driver.
    pub struct ModemEtmPeripherals {
        pub modem_etm: crate::ModemEtm,
    }

    /// Modem clock gates and MAC resets driven by the vendor modem clock devices; owned by the modem clock owner.
    pub struct ModemClockPeripherals {
        pub modem_syscon_radio: crate::ModemSysconRadio,
        pub modem_lpcon_shared_clock: crate::ModemLpconSharedClock,
    }

    /// Analog register I2C master hosts, read mask and host selection driven by the PHY.
    pub struct PhyI2cPeripherals {
        pub i2c_ana_mst: crate::I2cAnaMst,
    }

    /// PMU analog I2C power controls and PHY baseband configuration words driven by the PHY.
    pub struct PhyRadioPeripherals {
        pub pmu_radio: crate::PmuRadio,
        pub phy_baseband_config: crate::PhyBasebandConfig,
        pub lp_aon_radio: crate::LpAonRadio,
        pub apb_saradc_radio: crate::ApbSaradcRadio,
        pub pcr_radio: crate::PcrRadio,
    }

    /// ESP32-C5 Wi-Fi MAC register views owned by the Wi-Fi hardware lifecycle.
    pub struct WifiMacPeripherals {
        pub wifi_mac_aux_tsf_control: crate::WifiMacAuxTsfControl,
        pub wifi_mac_bssid_policy: crate::WifiMacBssidPolicy,
        pub wifi_mac_interface_address: crate::WifiMacInterfaceAddress,
        pub wifi_mac_rtc_timer_update: crate::WifiMacRtcTimerUpdate,
        pub wifi_mac_sta_beacon_filter: crate::WifiMacStaBeaconFilter,
        pub wifi_mac_sta_tsf_load: crate::WifiMacStaTsfLoad,
        pub wifi_mac_tx_common: crate::WifiMacTxCommon,
        pub wifi_mac_ersu_ack_rate: crate::WifiMacErsuAckRate,
    }

    /// Wi-Fi interrupt banks transferred from cold setup to the hard interrupt handlers.
    pub struct WifiInterruptPeripherals {
        pub wifi_mac_interrupt: crate::WifiMacInterrupt,
        pub wifi_mac_power_interrupt: crate::WifiMacPowerInterrupt,
    }

    /// Complete target-reviewed ownership decomposition.
    pub struct PeripheralPartitions {
        /// Source-qualified MMIO views retained for bit-use coverage. No production transaction or read-safe snapshot exposes these tokens.
        pub unexposed: UnexposedPeripherals,
        /// IEEE 802.15.4 MAC and source-specific interrupt-route registers owned by the IEEE 802.15.4 hardware lifecycle.
        pub ieee802154: Ieee802154Peripherals,
        /// Modem event-task matrix channels zero and one, programmed by the IEEE 802.15.4 driver.
        pub modem_etm: ModemEtmPeripherals,
        /// Modem clock gates and MAC resets driven by the vendor modem clock devices; owned by the modem clock owner.
        pub modem_clock: ModemClockPeripherals,
        /// Analog register I2C master hosts, read mask and host selection driven by the PHY.
        pub phy_i2c: PhyI2cPeripherals,
        /// PMU analog I2C power controls and PHY baseband configuration words driven by the PHY.
        pub phy_radio: PhyRadioPeripherals,
        /// ESP32-C5 Wi-Fi MAC register views owned by the Wi-Fi hardware lifecycle.
        pub wifi_mac: WifiMacPeripherals,
        /// Wi-Fi interrupt banks transferred from cold setup to the hard interrupt handlers.
        pub wifi_interrupts: WifiInterruptPeripherals,
    }

    /// Consume the singleton and apply the exhaustive target-owned partition.
    #[inline]
    pub fn partition(peripherals: crate::Peripherals) -> PeripheralPartitions {
        let crate::Peripherals {
            modem_ieee802154_observed,
            modem_wifi_mac_observed,
            modem_wifi_mac_power_observed,
            ieee802154_mac,
            ieee802154_interrupt_route,
            modem_etm,
            modem_syscon_radio,
            modem_lpcon_shared_clock,
            i2c_ana_mst,
            pmu_radio,
            phy_baseband_config,
            lp_aon_radio,
            apb_saradc_radio,
            pcr_radio,
            wifi_mac_aux_tsf_control,
            wifi_mac_bssid_policy,
            wifi_mac_interrupt,
            wifi_mac_power_interrupt,
            wifi_mac_rtc_timer_update,
            wifi_mac_sta_beacon_filter,
            wifi_mac_sta_tsf_load,
            wifi_mac_tx_common,
            wifi_mac_ersu_ack_rate,
            wifi_mac_interface_address,
        } = peripherals;
        PeripheralPartitions {
            unexposed: UnexposedPeripherals {
                modem_ieee802154_observed,
                modem_wifi_mac_observed,
                modem_wifi_mac_power_observed,
            },
            ieee802154: Ieee802154Peripherals {
                ieee802154_mac,
                ieee802154_interrupt_route,
            },
            modem_etm: ModemEtmPeripherals { modem_etm },
            modem_clock: ModemClockPeripherals {
                modem_syscon_radio,
                modem_lpcon_shared_clock,
            },
            phy_i2c: PhyI2cPeripherals { i2c_ana_mst },
            phy_radio: PhyRadioPeripherals {
                pmu_radio,
                phy_baseband_config,
                lp_aon_radio,
                apb_saradc_radio,
                pcr_radio,
            },
            wifi_mac: WifiMacPeripherals {
                wifi_mac_aux_tsf_control,
                wifi_mac_bssid_policy,
                wifi_mac_interface_address,
                wifi_mac_rtc_timer_update,
                wifi_mac_sta_beacon_filter,
                wifi_mac_sta_tsf_load,
                wifi_mac_tx_common,
                wifi_mac_ersu_ack_rate,
            },
            wifi_interrupts: WifiInterruptPeripherals {
                wifi_mac_interrupt,
                wifi_mac_power_interrupt,
            },
        }
    }
}

